(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["no"] = {"ui":{"skip":"Hopp til innholdet","back":"← Tilbake til AI-gile","lang.button":"Språk: {name}","lang.dialog":"Velg et språk","lang.search":"Søk etter språk","lang.none":"Fant ingen språk","lang.notYet":"{name} er ikke oversatt ennå","theme.aria":"Bytt tema: lyst, mørkt eller svart","theme.toLight":"Bytt til lyst tema","theme.toDark":"Bytt til mørkt tema","theme.toBlack":"Bytt til svart tema (helt svart, skånsomt for OLED-skjermer)","words.underline":"Understrek disse ordene på siden","words.underlineHelp":"Hold musepekeren over eller trykk på et ord med prikket strek for å se hva det betyr.","index.title":"AI-gile: AI-utviklerteamet ditt, på én tavle","index.description":"AI-gile er en kanban-tavle for AI-kodeteam. De jobber mens du sover; du får én kort bunke med ting du skal bestemme, teste og godkjenne.","hero.logoAlt":"AI-gile-tavleikon","hero.h1.html":"AI-utviklerteamet ditt, på én&nbsp;tavle.","hero.alpha":"🐣 Lukket pre-alfa","hero.alphaTitle":"Tidlig og uferdig: takk for at du prøver!","hero.lede":"De bygger mens du sover. Du våkner til én kort bunke: noen spørsmål, noen ting å teste, en lilla diamant eller to. Klikk, godkjenn, og tilbake til kaffen.","dl.windows":"Windows-app","dl.browser":"Kjør det i nettleseren","dl.messenger":"📱 Messenger til telefonen din","dl.soon":"Kommer snart","dl.notify":"🔔 Si fra når det åpner","dl.notifySmall":"Alfa eller beta","hero.secondary":"Agile, men teamet trenger aldri stand-up-kaffe. (De har stand-up likevel.)","pitch.h2":"AI-gile i så mange ord du vil","pitch.lede":"Velg en lengde, fra ett ord til 144. Hver lengde er sin egen beskrivelse, skrevet for akkurat den størrelsen. Dra i glideren eller bruk piltastene.","pitch.rangeLabel":"Lengde i ord","pitch.dice":"🎲 en annen versjon","pitch.words.one":"{n} ord","pitch.words.other":"{n} ord","pitch.letters.one":"{n} bokstav","pitch.letters.other":"{n} bokstaver","pitch.chars.one":"{n} tegn","pitch.chars.other":"{n} tegn","count.line.html.one":"{n} kort på tavlen akkurat nå","count.line.html.other":"{n} kort på tavlen akkurat nå","people.humans.html.one":"👥 {n} menneske","people.humans.html.other":"👥 {n} mennesker","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agenter","people.working.html.one":"⚡ {n} i arbeid akkurat nå","people.working.html.other":"⚡ {n} i arbeid akkurat nå","pre.title":"AI-gile: noe bygges","pre.description":"Her bygges det noe: en tavle der AI-team bygger det du ber om, og lærer deg underveis. Foreløpig lukket pre-alfa med venner.","pre.h1":"Her bygges det noe. 🤫","pre.line":"En tavle der AI-team bygger det du ber om, og lærer deg underveis. Foreløpig lukket pre-alfa med venner.","pre.btn":"🔔 Si fra når det åpner","pre.peek":"Bak glasset: den ekte tavla, direkte. Hvert kort er en farget stripe.","pre.peekFake":"Bak glasset: slik ser en tavle i arbeid ut.","features.aria":"Hva det gjør","f.pile.h":"Én bunke til deg","f.pile.html":"<b>Til deg</b> samler alt som venter på deg, på tvers av alle prosjekter: spørsmål, ting å teste, oppgaver bare et menneske kan gjøre. Køen din sier hva som er neste og hvor lang tid det tar.","f.sleep.h":"Team som jobber mens du sover","f.sleep.p":"Hvert prosjekt har en lead og et team av AI-agenter. Kommenter et kort, så våkner teamet, gjør jobben og leverer det tilbake med steg som et slitent menneske kan følge.","f.tester.h":"En AI-tester sjekker først","f.tester.p":"Før noe kommer til deg, følger en tester stegene i en kopi av appen og viser hva den så, med skjermbilde. Bla gjennom de som besto og godkjenn med ett klikk.","f.proof.h":"Bevis, ikke løfter","f.proof.p":"Hver levering viser hva som er endret: filene, diffen, skjermbildene. Du slipper å åpne hver app for å se om det er ferdig.","f.chat.h":"Snakk med leadene dine","f.chat.p":"En Discord-lignende sidestolpe: ett ikon per prosjekt, lilla diamanter for det som trenger deg. Send en lead en idé; den gjør den om til kort og en plan, med en ✅ Go-knapp.","f.tidy.h":"Holder orden selv","f.tidy.p":"Beslektede kort slås sammen, rotete titler rettes opp, og en token-sjekk holder koden slank. Færre ting å bytte mellom, mindre å tenke på.","f.private.h":"Ditt, på din egen datamaskin","f.private.li1":"Tavlen kjører på din egen maskin og svarer bare deg.","f.private.li2":"Private meldinger mellom mennesker er ende-til-ende-kryptert.","f.private.li3":"Ingen kontoer, ingen sporere, ingen informasjonskapsler.","f.lang.h":"På ditt språk","f.lang.p":"Over 120 språk, fra norsk, walisisk og japansk til pirat, Yoda og klingon, med en rask bryter tilbake til engelsk for fagspråket.","f.service.h":"Fra en idé til en ekte tjeneste","f.service.p":"Har du bygget noe med AI som folk nå bruker? Merk det som en tjeneste, så hjelper tavlen deg å drifte det godt: oppetidssjekker, en offentlig statusside, hendelser med en oppsummering, endringer som trenger et Go, sikkerhetskopier som sjekkes daglig. Hjelpen lærer deg hvert steg underveis.","msgr.h2":"AI-gile Messenger: teamet ditt i lomma","msgr.p1":"Snakk med AI-teamet ditt uten å åpne boardet. Chat med prosjektlederne og vennene dine, og se og svar på teststegene til et kort, alt fra telefonen.","msgr.p2":"For å koble den til skanner du en QR-kode på boardet ditt. Første gang? En vennlig demochat viser deg rundt.","msgr.when":"Android først, deretter en nettversjon for telefoner og iPhone.","msgr.who":"Prosjektlederen din","msgr.b1":"Fiksen for mørk modus er klar. Vil du ha teststegene?","msgr.b2":"Ja takk!","msgr.b3":"1. Åpne Innstillinger. 2. Velg Mørk. Ser det riktig ut?","tl.aria":"Tidslinje fra den første samtalen til veikartet","tl.h2":"Fra den første praten til det som kommer","tl.lede":"Ekte datoer og klokkeslett, i din egen tidssone. Etter i dag er det planen, uten lovede datoer.","tl.today":"I dag","tl.planned":"planlagt","tl.doing":"pågår","tl.cards.one":"{n} kort","tl.cards.other":"{n} kort","join.h2":"Bli med","join.lede":"AI-gile bygges av en skjeggete raring med AuDHD og noen kamper med den psykiske helsa, og et stort antall tålmodige agenter. Foreløpig er det privat, en lukket alfa med venner. Lyst til å prøve når det åpner?","join.btn":"Meld interesse","join.small":"Vi sender deg en e-post, ikke noe mer","footer.tag":"AI-gile. Ingen sporere, ingen informasjonskapsler, ingen stand-up-kaffe.","footer.licence":"Bedriftslisens","footer.status":"Status","footer.privacy":"Hva vi lagrer","footer.thanks":"Samtaler takket være ChilledChat","form.sending":"Sender…","form.failed":"Det gikk ikke: prøv igjen senere.","form.offline":"Fikk ikke kontakt med AI-gile: prøv igjen senere.","form.keep":"Vi bruker dette bare til å svare deg, og så sletter vi det. Ingen sporere, ingen informasjonskapsler.","form.keepLink":"Hva vi lagrer","interest.title":"AI-gile: si fra når alfaen åpner","interest.description":"Legg igjen e-postadressen din for å høre når AI-giles lukkede alfa eller beta åpner.","interest.h1":"🔔 Si fra når det åpner","interest.lede":"AI-gile er i lukket pre-alfa. Legg igjen e-postadressen din, så skriver vi én gang, når det er plass til deg.","interest.email":"E-postadressen din","interest.which":"Hvilken test?","interest.alpha":"Lukket alfa: tidlig, grov, mange endringer","interest.beta":"Beta: roligere, senere","interest.both":"Begge deler, det som kommer først","interest.submit":"Sett meg på listen","interest.thanks":"Takk! Du står på listen.","licence.title":"AI-gile: bedriftslisens","licence.description":"Bruker du AI-gile i bedriften din? Søk om en gratis bedriftslisens.","licence.h1":"📜 Bedriftslisens","licence.lede":"Bruker du AI-gile på jobb? Fortell oss hvem du er og hva du gjør. Hvis det gjør noe godt, er lisensen gratis.","licence.company":"Bedrift","licence.website":"Nettsted","licence.what":"Hva du gjør","licence.how":"Hvordan det hjelper verden","licence.email":"E-post","licence.submit":"Søk","licence.thanks":"Takk! Vi svarer på e-post.","status.title":"AI-gile-status","status.h1":"AI-gile-status","status.quiet":"Alt er rolig","status.intro":"Virker AI-gile akkurat nå? Denne siden sjekker nettstedet, tavledeling, samtaler og nedlastingen hvert 5. minutt.","status.up":"Virker (svarte på {ms} ms)","status.slow":"Svarte ikke på forrige sjekk, prøver igjen","status.down":"Nede: svarte ikke på de to siste sjekkene","status.svc.web":"Nettsted","status.svc.web.offers":"Dette nettstedet: hva AI-gile er, og interesseskjemaet","status.svc.boards":"Tavledeling","status.svc.boards.offers":"Offentlige tavler, meldinger mellom venner og invitasjoner","status.svc.calls":"Samtaler","status.svc.calls.offers":"Tale, video og skjermdeling i AI-gile","status.svc.download":"Nedlasting","status.svc.download.offers":"Windows-installasjonsprogrammet og invitasjonslenker","status.checking":"Sjekker…","status.offline":"Får ikke kontakt med statustjenesten akkurat nå (prøver igjen)","status.updated":"oppdatert {ago}","status.justNow":"nå nettopp","status.min":"{n} min siden","status.hours":"{n} t siden","status.days":"{n} d siden","privacy.title":"AI-gile: hva vi lagrer","privacy.h1":"Hva vi lagrer","privacy.lede":"Kortversjonen: bare det du sender oss, og ikke lenge.","privacy.only":"Bare det du sender oss: det du skriver i et skjema, som e-postadressen din. Ikke noe annet om deg.","privacy.sealed":"Det forsegles så serveren vår ikke kan lese det: i nettleseren din før det sendes (i en eldre nettleser i det øyeblikket det kommer fram). Bare vår egen tavle kan åpne det.","privacy.server":"Det slettes fra serveren så snart det når tavlen vår. Det som fortsatt ligger der etter 30 dager, slettes uansett.","privacy.board":"Vi beholder det på tavlen vår bare til vi har svart deg, og så sletter vi det der også.","privacy.none":"Ingen sporere, ingen informasjonskapsler, ingen analyse.","privacy.local":"Språket ditt og valget mellom lyst og mørkt blir værende i din egen nettleser. De sendes aldri til oss.","privacy.ask":"Vil du ha det slettet før? Svar på e-posten vår og si fra.","live.h2":"Se det bli bygget, direkte","live.caption":"Hvert kort er skjult: du ser formen på arbeidet, ikke ordene.","live.watching.one":"direkte: {n} ser på","live.watching.other":"direkte: {n} ser på","live.last.now":"Siste kort ble flyttet nettopp","live.last.min.one":"Siste kort ble flyttet for {n} min. siden","live.last.min.other":"Siste kort ble flyttet for {n} min. siden","live.last.hour.one":"Siste kort ble flyttet for {n} time siden","live.last.hour.other":"Siste kort ble flyttet for {n} timer siden","live.last.day.one":"Siste kort ble flyttet for {n} dag siden","live.last.day.other":"Siste kort ble flyttet for {n} dager siden","live.offline":"Direktetavlen tar en liten pause. Kom innom igjen snart.","live.cols":"Backlog|Å gjøre|Pågår|Teamet sjekker|Du skal teste|Til teamet|Ferdig"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboter.","Delegert."]},{"n":2,"texts":["Roboter jobber.","Agenter, ordnet.","Idéer, bygget."]},{"n":3,"texts":["Kanban for roboter.","Idéer blir funksjoner.","Gratis, lokalt, testet."]},{"n":5,"texts":["En kanban-tavle der agentene bygger.","Du skriver kort. Agenter bygger.","Gratis, lokalt, testet, litt tullete."]},{"n":8,"texts":["En gratis kanban-tavle der AI-agenter gjør selve jobben.","Skriv en idé. Agentene bygger den. Du godkjenner.","Agile for ett menneske og mange tålmodige roboter."]},{"n":13,"texts":["En kanban-tavle på datamaskinen din der AI-agenter plukker opp kortene.","Skriv en idé. Et team av agenter bygger den. En tester sjekker den.","Gratis, ingen kontoer, ingen sporere: en tavle, noen roboter, og du som sjef."]},{"n":21,"texts":["AI-gile er en kanban-tavle for å jobbe med AI-kodeagenter. De plukker opp kortene; du tester og godkjenner dem.","Hvert prosjekt får en lead og et team av AI-agenter. Kommenter hvilket som helst kort, så setter teamet i gang.","En gratis, personlig oppgavetavle som kjører på din egen datamaskin. Arbeiderne er roboter. Den som sier ja, er du."]},{"n":34,"texts":["Du legger idéer på en tavle. Et team av AI-agenter gjør dem om til fungerende funksjoner, tester dem og leverer dem tilbake med steg du kan prøve. Ingenting regnes som ferdig før du sier det.","AI-gile er en hjemmelaget kanban-tavle som Rich bygde med mye hjelp fra agentene den nå styrer. Den er gratis, kjører på datamaskinen din og deles med venner, ikke selges.","Tenk deg en vanlig kanban-tavle, med kolonner fra Backlog til Ferdig, bare at kortene plukkes opp av AI-agenter. De rapporterer framdrift, spør når de står fast, og venter alltid på tommelen opp fra deg."]},{"n":55,"texts":["AI-gile er en kanban-tavle der teamet består av AI-agenter. Hvert prosjekt har en lead som planlegger arbeidet og hjelpere som bygger det. Når en funksjon er klar, prøver en AI-tester den og tar et skjermbilde, og så havner den i bunken din. Godkjenn den, eller kommenter, så jobber de om den.","Det begynte som én persons måte å holde styr på mange AI-kodeøkter samtidig, og vokste til en ordentlig tavle. Den kjører på maskinen din, krever ingen konto og har ingen sporere. Den er gratis for venner og nysgjerrige. Den er også uferdig, så regn med noen skarpe kanter og en og annen overraskelse.","Her er den ærlige versjonen. Du må fortsatt komme med idéene, og du må fortsatt sjekke resultatene. Det AI-gile gjør, er alt imellom: det holder kortene i orden, vekker riktig agent når du kommenterer, viser nøyaktig hva som er endret, og samler alt i én kort bunke til deg."]},{"n":89,"texts":["AI-gile er en gratis kanban-tavle som du kjører på din egen datamaskin. I stedet for mennesker har hvert prosjekt et team av AI-agenter: en lead som gjør idéene dine om til kort og en plan, og hjelpere som plukker opp kortene i prioritert rekkefølge. Når noe er bygget, følger en AI-tester teststegene og viser deg hva den så. Så venter det i én bunke som heter Til deg. Du godkjenner det, eller du kommenterer og teamet prøver på nytt. Ingenting havner noen gang i Ferdig uten deg.","Noen funksjoner du kanskje ikke venter. En nattevakt holder Å gjøre-kolonnen fylt opp mens du sover, og velger kort som ikke trenger svar fra deg. En tokenteller viser hvor mye agentene har brukt i dag og denne uka, og Ingen token-modus ber dem slutte å bruke. Du kan sende meldinger til venner, og private meldinger er ende-til-ende-kryptert. Tavlen snakker rundt 120 språk, blant andre norsk, pirat og klingon. Ingenting av det koster en krone, og ingen prøver å selge det til deg heller.","AI-gile er et lite, personlig prosjekt, ikke et selskap. Rich ville ta vare på flere AI-kodeprosjekter uten å åpne hver app for å sjekke dem, så han og agentene bygde en tavle til det, og brukte så tavlen til å bygge resten av seg selv. Den er i lukket pre-alfa, som betyr at den virker, stort sett, for en håndfull venner. Det finnes ingen prisside, ingen nyhetsbrev og ingen vekstplan. Høres det nyttig ut, kan du be om å få prøve den når den åpner litt mer."]},{"n":144,"texts":["AI-gile er en kanban-tavle for ett menneske og mange AI-agenter. Den kjører på din egen datamaskin og er helt gratis. Du legger til prosjekter, og hvert prosjekt får en lead og et lite team. Du prater med leaden, litt som på Discord, og beskriver en idé; leaden gjør den om til kort og en plan, og venter på at du trykker Go. Teamet jobber seg gjennom kortene i prioritert rekkefølge, med et enkelt kommandolinjeverktøy laget for språkmodeller. Før noe kommer tilbake til deg, følger en AI-tester stegene i en kopi av appen og legger ved et skjermbilde. Ferdig arbeid havner i bunken din, med de endrede filene og diffen. Du godkjenner det, eller du legger igjen en kommentar, så våkner teamet og prøver på nytt. Bare du kan flytte et kort til Ferdig.","En dag med AI-gile, omtrent. Om kvelden legger du igjen noen kommentarer: denne knappen står på feil sted, den listen bør sorteres, kunne vi fått mørk modus. Du går og legger deg. Agentene leser kommentarene, gjør endringene, tester dem og leverer dem tilbake til deg. Hvis Å gjøre går tom, fyller nattevakten opp fra backlogen med kort som ikke trenger noe svar fra deg. Om morgenen ligger det én kort bunke: et par spørsmål og noen ting å prøve, hver med steg som en søvnig person kan følge og et skjermbilde av at det virker. Du klikker deg gjennom, godkjenner de gode og sender resten tilbake. En tokenteller viser hva det hele brukte, og Ingen token-modus finnes for magre uker. Så spiser du frokost, noe agentene ikke kan hjelpe med ennå.","Først, hva AI-gile ikke er. Det er ikke en oppstartsbedrift, det er ikke til salgs, og ingen samler inn dataene dine. Det er en gratis tavle som kjører på datamaskinen din, uten kontoer, sporere eller informasjonskapsler. Det det er: ett ryddig sted å se alle AI-kodeprosjektene dine samtidig, med et team av agenter som tar kortene og du som tar avgjørelsene. Det slår sammen beslektede kort, retter opp rotete titler og følger med på hvor slank koden holder seg. Det snakker rundt 120 språk, fra norsk til pirat og klingon. Venner kan sende hverandre meldinger, privat og kryptert. Det er bygget av Rich og et stort antall tålmodige agenter, som for det meste brukte det selv. Det er i lukket pre-alfa, så det er grovt noen steder. Høres det gøy ut, spør pent, så kommer du kanskje tidlig inn."]}],"quips":{"1":"Ett ord. Frekt. Kanskje for frekt.","3":"Tre ord. Allerede ærligere enn de fleste produktsider.","8":"Åtte ord. Fortsatt kortere enn en stand-up.","21":"Lengdene er forresten story points. Selvfølgelig er de det.","55":"Femtifem ord. To kort ble ferdige mens du leste det.","144":"Det var den lange. Det finnes ingen 233. Agentene har gått og lagt seg."}},"timeline":{"first-idea.name":"Den første idéen","first-idea.line":"Den aller første samtalen, før det fantes en eneste linje kode.","first-board.name":"Første tavle","first-board.line":"En tavle som holder styr på sin egen bygging: kort, kolonner, dra og slipp, prosjekter.","team-roles.name":"Team og roller","team-roles.line":"Agentprofiler, teammaler, rom og hvem som gjør hva.","install.name":"Installering og utgivelser","install.line":"En zip-fil en venn kan installere, selvoppdatering, kanaler og tilbakerulling.","usage-saver.name":"Bruksbesparer","usage-saver.line":"Måle hva kjøringer koster, holde koden slank, spare på grensen din.","friends.name":"Venner og deling","friends.line":"Private meldinger, et kryptert relé, invitasjoner, roller og delte prosjekter.","languages.name":"Språk","languages.line":"Hver skjermtekst i en språkfil, med nederlandsk og flamsk først.","ai-tester.name":"AI-tester","ai-tester.line":"En tester sjekker hver levering først og viser hva den så.","website.name":"Nettstedet","website.line":"aigile.lol, teaseren og denne tidslinjen.","streaming.name":"Chat og streaming","streaming.line":"Discord, Twitch, OBS, strømmermodus, GIF-er og emojier.","no-ai.name":"Utgave uten AI","no-ai.line":"En tavle for folk som koder uten AI, og offentlige tavler.","night-watch.name":"Nattevakt","night-watch.line":"En vaktmann og en Scrum Master holder teamene på sporet mens du sover.","p-more.name":"Alt det andre","p-more.line":"Mindre idéer som fortsatt venter på tur.","p-android.name":"Telefon og Android","p-android.line":"Nå tavlen din fra telefonen, deretter en egen Android-app.","p-release.name":"Alfa og videre","p-release.line":"Lukket alfa, det levende nettstedet, så beta.","p-languages.name":"Flere språk","p-languages.line":"Mer enn hundre språk, og en fordypningsmodus for dem som lærer.","p-engines.name":"Flere AI-motorer","p-engines.line":"Velg Claude, Codex eller Gemini for hver agent.","p-pro.name":"Profesjonell praksis","p-pro.line":"Risikomerker, sammenslåingsporter, hendelseskort og rekkverk.","p-self.name":"Å ta vare på deg","p-self.line":"Trøtt modus, egenomsorgspåminnelser og 4:20.","p-servers.name":"Servere og skalering","p-servers.line":"Globale serverinnstillinger, roller og planlegging for vekst.","p-livestream.name":"Streamingtillegg","p-livestream.line":"Twitch-chat, egne emojier og en offentlig direktevisning."},"words":{"button":"📖 Fagspråk","h":"📖 Ord forklart","intro":"Ordene du møter i AI-gile, på vanlig norsk: å bygge, å endre trygt, å holde det i gang for dem som bruker det, og å jobbe som et team med AI.","search":"Søk etter et ord…","none":"Ingen ord passer.","close":"Lukk","count":{"one":"{count} ord","other":"{count} ord"},"groups":[{"id":"build","name":"🛠️ Å bygge"},{"id":"change","name":"🔀 Å endre trygt"},{"id":"run","name":"🛎️ Å drifte en tjeneste"},{"id":"team","name":"🤝 Å jobbe som et team (og med AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Prosjektets mappe med kode og hele historikken av commits, vanligvis også lagret på GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"En egen arbeidslinje i koden, så endringer kan gjøres uten å røre hovedversjonen.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Et lagret øyeblikksbilde av koden, med et kort notat om hva som er endret. Du kan alltid gå tilbake til ett.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Å sende lagrede øyeblikksbilder (commits) fra denne datamaskinen opp til GitHub, så de er sikkerhetskopiert og delt."},{"id":"merge","g":"build","word":"Merge","text":"Å slå endringene fra en branch sammen med hovedversjonen igjen."},{"id":"pr","g":"build","word":"Pull request","text":"Å be om at endringene i en branch blir sjekket og slått sammen med hovedversjonen.","also":["PR"]},{"id":"refactor","g":"build","word":"Refaktorering","text":"Å rydde i koden uten å endre hva den gjør: mindre filer, tydeligere navn, mindre gjentakelse."},{"id":"bug","g":"build","word":"Bug","text":"Noe som ikke fungerer slik det skal.","also":["bugs","feil"]},{"id":"test","g":"build","word":"Test","text":"Å prøve et ferdig stykke arbeid for å sjekke at det gjør det som ble bedt om, før du godtar det.","also":["tester","teste","testes"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Kort for quality assurance (kvalitetssikring): de automatiske sjekkene som kjører før noe går live. Når QA er rød, har noe feilet, og det kan ikke gå live før det er rettet.","also":["kvalitetssjekker","kvalitetssjekk","kvalitetssikring"]},{"id":"deploy","g":"change","word":"Deploy","text":"Å sende en ny versjon live, for eksempel til en server der folk bruker den."},{"id":"release","g":"change","word":"Utgivelse","text":"En navngitt pakke med ferdig arbeid som går live samtidig, med korte notater om hva som er endret. 🚀 Utgivelser skriver notatene ut fra de ferdige kortene.","also":["utgivelser","utgivelsen","utgivelsene","release"]},{"id":"rollback","g":"change","word":"Rulle tilbake","text":"Å gå tilbake til den siste versjonen som virket, når en ny skaper trøbbel. I AI-gile lager det en sjekkliste av angrertrinnene som står på hver endring.","also":["rull tilbake","tilbakerulling","rullet tilbake","rollback"]},{"id":"live","g":"change","word":"Live","text":"Den ekte versjonen folk bruker, i motsetning til en kopi for å prøve ting ut. Utviklere kaller det også produksjon.","also":["produksjon","i produksjon","prod"],"noTip":1},{"id":"change","g":"change","word":"Endring","text":"En planlagt endring av noe folk er avhengige av, skrevet ned først: hva, hvorfor, risikoen, når, og hvordan den rulles tilbake. Start en med 🔀 Send inn en endring.","also":["endringer","endringen","endringsforespørsel","endringsforespørsler"],"noTip":1},{"id":"risk","g":"change","word":"Risiko","text":"Noe som kan gå galt, med poeng etter hvor sannsynlig og hvor ille det ville vært. ⚠️ Risikoer holder dem i én liste, høyeste poengsum først, hver med en dato for å se på den igjen.","also":["risikoer","risikoen","risikoregister"]},{"id":"chgwin","g":"change","word":"Endringsvindu","text":"Tidene da endringer kan gå live, for eksempel en rolig tirsdagskveld. Utenfor et vindu kan et endringskort ikke bli ferdig, med mindre det er en nødsituasjon.","also":["endringsvinduer","endringsvinduet","vindu"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"En rask avstemning like før en endring går live: alle som må godkjenne, sier Go eller No go. Den går bare videre når de er enige.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Godkjenning","text":"Å vente på et ja før arbeidet starter. Et kort en venn sender inn, eller en endring, venter i ✅ Godkjenninger til du godkjenner eller avslår det.","also":["godkjenninger","godkjenningen"]},{"id":"quiettime","g":"change","word":"Stille tid","text":"En periode, som en strøm, en demo eller natten, der ingenting går live. Teamene fortsetter å jobbe og teste, men det å gå live venter til den er over. Andre steder kalles det endringsfrys.","also":["stille tider","endringsfrys"]},{"id":"service","g":"run","word":"Tjeneste","text":"Noe du har bygget som folk er avhengige av, som et nettsted eller en app, og som blir passet på så det fortsetter å virke. Kryss av for «Dette prosjektet er en tjeneste» og si hva den tilbyr, hvem som bruker den og hvem som har vakt.","also":["tjenester","tjenesten","tjenestene"]},{"id":"uptime","g":"run","word":"Oppetidssjekk","text":"En automatisk sjekk, med noen minutters mellomrom, av at tjenesten din fortsatt svarer. Feiler den flere ganger på rad, åpner AI-gile et hendelseskort av seg selv.","also":["oppetid","oppetidssjekker","uptime"]},{"id":"statuspage","g":"run","word":"Statusside","text":"En offentlig side som viser om en tjeneste virker (grønn, oransje eller rød) med siste oppdatering, så de som bruker den kan sjekke selv i stedet for å spørre.","also":["statussider","statussiden"]},{"id":"incident","g":"run","word":"Hendelse","text":"Noe som er ødelagt for dem som bruker det akkurat nå, for eksempel at nettstedet er nede. Et 🔥 hendelseskort går foran i køen: å få det til å virke igjen kommer først.","also":["hendelser","hendelsen","hendelsene","hendelseskort"]},{"id":"major","g":"run","word":"Stor hendelse","text":"En stor hendelse: mange er rammet, eller penger eller data står på spill. Én knapp setter alle team på den (sverm), vekker den som har vakt og ber om en statusoppdatering hvert 30. minutt.","also":["store hendelser","større hendelse"]},{"id":"oncall","g":"run","word":"Vakt","text":"Å være den som svarer når noe går i stykker, også om natten. Hver tjeneste har et vakthavende teammedlem som vekkes først ved hendelser.","also":["har vakt","vakthavende","på vakt","on-call"]},{"id":"replyby","g":"run","word":"Svarfrist","text":"Hvor lenge et kort kan vente på et første svar, for eksempel en time for en hendelse. Etter det får det en rød klokke, så ingenting blir glemt i det stille. Kalles også et responsmål.","also":["svarfrister","svarfristen","responsmål"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Et kort tilbakeblikk etter en hendelse: hva skjedde, hva hjalp og hva bør endres, uten å legge skylden på noen. En hendelse kan ikke lukkes uten en.","also":["post-mortems","postmortem","etterevaluering"]},{"id":"problem","g":"run","word":"Problem","text":"Den skjulte årsaken bak én eller flere hendelser. Et 🧩 problemkort samler hendelser som stadig kommer tilbake, så årsaken blir funnet og rettet for godt.","also":["problemer","problemet","problemkort"],"noTip":1},{"id":"rootcause","g":"run","word":"Rotårsak","text":"Den egentlige grunnen til at noe gikk i stykker, ikke bare det du så gå galt. Rett rotårsaken, så slutter hendelsen å komme tilbake.","also":["rotårsaker","rotårsaken"]},{"id":"workaround","g":"run","word":"Omvei","text":"En måte å holde ting i gang på til den ekte rettingen er klar, som å starte noe på nytt når det henger seg. Den skrives på problemkortet, så ingen må finne den ut på nytt.","also":["omveier","omveien","workaround"]},{"id":"knownerror","g":"run","word":"Kjent feil","text":"Et problem der årsaken er forstått og det finnes en omvei, men som ikke er rettet ennå. 🧩 Kjente feil lister dem opp, så alle bruker omveien i stedet for å grave på nytt.","also":["kjente feil","den kjente feilen"]},{"id":"runbook","g":"run","word":"Runbook","text":"Trinnvise instruksjoner for å rette en kjent type trøbbel, så det blir gjort likt og raskt hver gang. Etter en stor hendelse kan teamet foreslå en som du gir OK til.","also":["runbooks","runbooken"]},{"id":"backup","g":"run","word":"Sikkerhetskopi","text":"En lagret kopi av dataene dine fra tidligere, å falle tilbake på hvis noe går tapt eller blir skadet. AI-gile tar en sikkerhetskopi av tavlene dine hver dag.","also":["sikkerhetskopier","sikkerhetskopien","backup"]},{"id":"restore","g":"run","word":"Gjenoppretting","text":"Å legge data tilbake fra en sikkerhetskopi. En sikkerhetskopi teller egentlig først når du vet at den kan gjenopprettes, så det er lurt å prøve av og til.","also":["gjenopprette","gjenopprett","gjenopprettet"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ideer og arbeid som ikke er planlagt ennå. Ingenting der blir jobbet med før det flyttes til Å gjøre."},{"id":"sprint","g":"team","word":"Sprint","text":"En kort arbeidsperiode (ofte en uke eller to) med et avtalt sett kort som skal ferdigstilles.","also":["sprinter","sprint","sprinten"]},{"id":"standup","g":"team","word":"Stand-up","text":"En rask statusrunde: hva hvert teammedlem gjorde, hva de gjør videre, og hva som stopper dem.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Et board med kolonner (Å gjøre, Pågår, Ferdig) der kortene flytter seg fra venstre mot høyre etter hvert som arbeidet skjer."},{"id":"wip","g":"team","word":"WIP-grense","text":"Work in progress: det største antallet kort en kolonne bør ha, så teamet blir ferdig med ting før det starter på nye.","also":["WIP"]},{"id":"dod","g":"team","word":"Definisjon av Ferdig","text":"Teamets korte sjekkliste for hva «ferdig» betyr, som testet og forklart, før et kort blir gitt til deg. Tvillingen, Definisjon av Klart til start, sier når et kort er tydelig nok til å begynne.","also":["Definisjon av Klart til start","Definition of Done","Definition of Ready"]},{"id":"testpile","g":"team","word":"Testbunke","text":"De ferdige kortene som venter på at du prøver dem, ett etter ett. Godta ett eller send det tilbake med en merknad, så kommer det neste.","also":["testbunker","testbunken"]},{"id":"retro","g":"team","word":"Retro","text":"Et tilbakeblikk på hvordan teamet jobber, for å bli enige om én ting å gjøre bedre. I AI-gile foreslår en retro en endring i teamets arbeidsmåte, og du sier Go eller Ikke ennå.","also":["retroer","retrospektiv","retrospektiver"]},{"id":"peerreview","g":"team","word":"Kollegagjennomgang","text":"Et ekstra par øyne: en annen AI sjekker arbeidet på hvert kort før det når deg, så færre feil slipper gjennom.","also":["kodegjennomgang","peer review"]},{"id":"swarm","g":"team","word":"Sverm","text":"Alle mann til pumpene: hvert team legger annet arbeid til side for å hjelpe på ett hasteprosjekt til det er i orden. Andre prosjekter venter så lenge.","also":["sverming","svermen"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Den som holder arbeidet i flyt: ser kort som står fast, dytter på teamene og minner deg på hva som venter. I AI-gile gjør Lead Scrum Master dette på tvers av alle prosjekter.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"En AI som jobber på egen hånd med en oppgave: leser koden, gjør endringer, kjører sjekker og melder tilbake.","also":["agenter"]},{"id":"token","g":"team","word":"Token","text":"Enheten AI-bruk telles i: omtrent noen få bokstaver tekst som leses eller skrives. Færre tokens, mer igjen av abonnementet.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"En liten kommando som kjører av seg selv på et bestemt tidspunkt, f.eks. når en AI-økt starter, så teamet hører kommentarene dine.","also":["hooks"]}]}};
